SELECT EXISTS (SELECT 1 FROM byai.po_users u WHERE u.user_id=#{actorId}
  AND u.state='A' AND UPPER(COALESCE(u.is_locked,'N'))!='Y'
  AND (LOWER(u.user_code)='adminvip' OR EXISTS (
    SELECT 1 FROM byai.tenant_user_membership m WHERE m.user_id=u.user_id
      AND m.enterprise_id=#{enterpriseId} AND m.status='ACTIVE'
  )))
